const chapters = [{"number": 1, "title": "De onde eu vim", "heading": "A menina que sentia demais", "paragraphs": ["Desde muito nova escutava que ser indecisa e “sentir demais” eram meus dois maiores defeitos. E, para ajudar, eu era nerd. Aos 17 anos, já tinha feito o ENEM e tinha nota para entrar em cursos bem diferentes sem precisar prestar vestibular. Ainda assim, não sabia qual escolher. Quando se tem muitos interesses e cada escolha parece fechar outras portas, decidir pode demorar um pouco mais.", "Minha família era humilde, e meus pais se preocupavam com o ensino que eu receberia. Estudei em escola pública, mas, na minha cidade, a falta de professores, o ensino precário e a marginalidade em algumas escolas nos fizeram procurar outra saída para o ensino médio. Consegui uma bolsa que pagava parte da escola. Para dar a minha contribuição de “centavos” e ajudar meus pais a bancar o restante, aos 16 anos comecei a trabalhar como menor aprendiz em um banco."]}, {"number": 2, "title": "As experiências que juntaram as peças", "heading": "Um espaço que precisava contar uma história", "paragraphs": ["Em uma feira de negócios, participei da criação de um estande imersivo. Era um projeto milionário, construído com muita gente (fornecedores, montadores, técnicos) e muitas decisões que precisavam conversar entre si. Mas a equipe que pensava e coordenava a experiência tinha só três pessoas, e eu era uma delas. De um lado, a história da empresa; do outro, uma pessoa atravessando corredores cheios de estímulos, com poucos minutos para decidir se entraria ali. A gente precisava pensar no encontro entre essas duas coisas.", "Havia imagens, arquitetura, movimento, som e um percurso físico. Uma cena podia ser impressionante sozinha e, dentro do estande, não ajudar a contar nada. Para onde as pessoas olhariam primeiro? Em quanto tempo entenderiam o que aquela empresa fazia? O que levariam consigo ao sair? Foi ali que uma pergunta antiga voltou de outro jeito: queríamos criar uma experiência bonita, claro, mas eu também queria saber o que ela faria alguém perceber."]}, {"number": 3, "title": "O que chamo de BCS", "heading": "Um conceito em construção", "paragraphs": ["BCS é a sigla para Behavioral Creative Strategy.", "É o conceito que criei para conectar três coisas que, no meu trabalho, não deveriam andar separadas: o comportamento de quem vive uma experiência, a maneira como essa experiência é percebida e as escolhas de quem a constrói."]}, {"number": 4, "title": "Por que perceber muda uma decisão"}, {"number": 5, "title": "Como uso esse olhar no trabalho"}, {"number": 6, "title": "Uma profissão possível"}, {"number": 7, "title": "O que uma marca deixa na memória"}, {"number": 8, "title": "O que uma imagem mostra e o que ela deixa de fora"}, {"number": 9, "title": "Uma história que ajuda alguém a escolher"}, {"number": 10, "title": "Aprender com o que acontece de verdade"}, {"number": 11, "title": "O trabalho de quem conecta as partes"}, {"number": 12, "title": "O anúncio também faz parte do caminho"}, {"number": 13, "title": "A pergunta continua"}];
const pillars=[
 {question:'Quem vai encontrar aquilo?\nO que essa pessoa procura?',body:'Antes de decidir o que criar, tento entender a situação. Quem vai encontrar aquilo? O que essa pessoa já sabe? O que procura? Que perguntas faz? Onde fica confusa?'},
 {question:'O que alguém vai perceber?\nA linguagem aproxima ou complica?',body:'Com o que aprendi, penso no que a pessoa vai ver, ouvir e experimentar. Que informação aparece primeiro? A fotografia representa bem o lugar? A linguagem aproxima ou complica? É fácil entender as opções?'},
 {question:'A ideia ajudou de verdade?\nO que aprendemos com ela?',body:'Escolho o que mudar, explico por que acho que isso pode ajudar e observo o que acontece. Posso comparar duas versões quando fizer sentido, conversar de novo com as pessoas ou acompanhar as dúvidas que chegam ao atendimento.'}
];
const tabs=[...document.querySelectorAll('[data-pillar]')];
function activatePillar(n){tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===n));tab.tabIndex=i===n?0:-1});document.getElementById('conceito-painel').setAttribute('aria-labelledby',tabs[n].id);const q=document.getElementById('pillar-question');q.replaceChildren();pillars[n].question.split('\n').forEach((line,i)=>{if(i)q.append(document.createElement('br'));q.append(document.createTextNode(line))});document.getElementById('pillar-body').textContent=pillars[n].body;}
tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activatePillar(i));tab.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%3;else if(e.key==='ArrowLeft')n=(i+2)%3;else if(e.key==='Home')n=0;else if(e.key==='End')n=2;else return;e.preventDefault();activatePillar(n);tabs[n].focus();})});
const previews=chapters.filter(chapter=>Array.isArray(chapter.paragraphs));
const list=document.getElementById('chapter-list');
chapters.forEach(chapter=>{const row=document.createElement('div');row.className='chapter-row';const n=document.createElement('span');n.textContent=String(chapter.number).padStart(2,'0');const h=document.createElement('h3');h.textContent=chapter.title;row.append(n,h);if(chapter.paragraphs){const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent='Ler trecho';button.dataset.read=chapter.number;button.setAttribute('aria-label','Ler trecho do capítulo '+chapter.number+': '+chapter.title);row.append(button)}list.append(row)});
const reader=document.getElementById('reader');let current=0;
function showChapter(n){if(!Number.isInteger(n)||n<0||n>=previews.length)return false;current=n;const ch=previews[current];document.getElementById('reader-label').textContent='CAPÍTULO '+ch.number;document.getElementById('reader-title').textContent=ch.title;document.getElementById('reader-section').textContent=ch.heading;const text=document.getElementById('reader-text');text.replaceChildren();ch.paragraphs.forEach(para=>{const p=document.createElement('p');p.textContent=para;text.append(p)});document.getElementById('reader-counter').textContent=String(ch.number).padStart(2,'0')+' / '+String(previews.length).padStart(2,'0');document.getElementById('reader-prev').disabled=current===0;document.getElementById('reader-next').disabled=current===previews.length-1;reader.scrollTop=0;return true;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-read]');if(!b)return;if(!showChapter(Number(b.dataset.read)-1))return;if(!reader.open)reader.showModal();document.querySelector('.reader-close').focus()});
document.querySelector('.reader-close').addEventListener('click',()=>reader.close());
reader.addEventListener('click',e=>{if(e.target===reader){const r=reader.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)reader.close()}});
document.getElementById('reader-prev').addEventListener('click',()=>showChapter(current-1));document.getElementById('reader-next').addEventListener('click',()=>showChapter(current+1));
